tests:
test({ sr: 'nalazi vrednost u sredini', en: 'finds a value in the middle' }, () => {
  expect(hasValue([1, 2, 3], 2)).toBe(true);
});
test({ sr: 'vrednost koje nema daje false', en: 'a missing value gives false' }, () => {
  expect(hasValue(['a'], 'b')).toBe(false);
});
test({ sr: 'nalazi i prvi element', en: 'finds the first element too' }, () => {
  expect(hasValue(['a', 'b'], 'a')).toBe(true);
});

hiddenTests:
test('NaN is found, unlike with indexOf', () => {
  expect(hasValue([1, NaN], NaN)).toBe(true);
});
test('strict comparison: the number 1 and the text "1" are different', () => {
  expect(hasValue(['1', 2], 1)).toBe(false);
});
test('null and undefined are different', () => {
  expect(hasValue([null], undefined)).toBe(false);
});
test('an empty array contains nothing', () => {
  expect(hasValue([], 1)).toBe(false);
});
test('does not change the input', () => {
  const input = [1, 2];
  hasValue(input, 2);
  expect(input).toEqual([1, 2]);
});

solutions.code:
function hasValue(items, value) {
  for (const item of items) {
    if (item === value) return true;
    if (Number.isNaN(item) && Number.isNaN(value)) return true;
  }
  return false;
}
